using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.CostCenters;using Namaa.Api.Extensions;using Namaa.Application.CostCenters.Commands.CreateCostCenter;using Namaa.Application.CostCenters.Commands.UpdateCostCenter;using Namaa.Application.CostCenters.Queries.GetCostCenterById;using Namaa.Application.CostCenters.Queries.GetCostCenters;namespace Namaa.Api.Controllers;[ApiController][Route("api/cost-centers")]public sealed class CostCentersController(ISender sender):ControllerBase{[HttpPost]public async Task<IActionResult>Create(CreateCostCenterRequest request,CancellationToken cancellationToken){var result=await sender.Send(new CreateCostCenterCommand(request.CostCenterCode,request.Name,request.Description,request.ParentCostCenterId,request.BranchId),cancellationToken);return result.IsFailure?result.ToActionResult(this):CreatedAtAction(nameof(GetById),new{id=result.Value.Id},result.Value);}[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetCostCentersQuery(),cancellationToken)).ToActionResult(this);[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetCostCenterByIdQuery(id),cancellationToken)).ToActionResult(this);[HttpPut("{id:long}")]public async Task<IActionResult>Update(long id,UpdateCostCenterRequest request,CancellationToken cancellationToken)=>(await sender.Send(new UpdateCostCenterCommand(id,request.Name,request.Description,request.ParentCostCenterId,request.BranchId,request.RowVersion),cancellationToken)).ToActionResult(this);}
